package io.github.diodeme.ji.telemetry;

import java.util.Map;
import java.util.concurrent.CompletionStage;
import java.util.function.Function;

final class NoopTelemetryContext implements TelemetrySpan {
    static final NoopTelemetryContext INSTANCE = new NoopTelemetryContext();

    private NoopTelemetryContext() {}

    @Override
    public <T> T inSpan(SpanSpec spec, Function<TelemetrySpan, T> callback) {
        return callback.apply(this);
    }

    @Override
    public <T> CompletionStage<T> inSpanAsync(SpanSpec spec, Function<TelemetrySpan, CompletionStage<T>> callback) {
        return callback.apply(this);
    }

    @Override public void setAttributes(Map<String, TelemetryValue> attributes) {}
    @Override public void addEvent(String name, Map<String, TelemetryValue> attributes) {}
    @Override public void recordMetric(MetricPoint point) {}
    @Override public void setStatus(SpanStatus status) {}
    @Override public void settle(boolean failed) {}
    @Override public SpanParent childParent() { return SpanParent.root(); }
}
